void nfcmrvl_nci_unregister_dev(struct nfcmrvl_private *priv)
{
	// Check if priv is NULL
	if (priv == NULL) {
		return;
	}

	struct nci_dev *ndev = priv->ndev;
	bool fw_download_in_progress = false;

	// Check if ndev and nfc_dev are not NULL before accessing
	if (ndev && ndev->nfc_dev) {
		fw_download_in_progress = ndev->nfc_dev->fw_download_in_progress;
	}

	nci_unregister_device(ndev);

	// Adjusted order: Deinit before abort to ensure proper cleanup
	nfcmrvl_fw_dnld_deinit(priv);
	if (fw_download_in_progress) {
		nfcmrvl_fw_dnld_abort(priv);
	}

	// Check if reset_n_io is valid before using
	if (gpio_is_valid(priv->config.reset_n_io)) {
		gpio_free(priv->config.reset_n_io);
	}

	// Safe as per investigation
	nci_free_device(ndev);

	// Finally, free priv
	kfree(priv);
}
