const int64_t abs_max =
    std::max(static_cast<int64_t>(std::abs(min_per_channel)), 
             static_cast<int64_t>(std::abs(max_per_channel)));
// Ensure abs_max is within int32_t range before casting
OP_REQUIRES(ctx, abs_max <= static_cast<int64_t>(INT32_MAX) && abs_max >= static_cast<int64_t>(INT32_MIN),
            errors::InvalidArgument("abs_max exceeds int32_t range"));
const int32_t abs_max_int32 = static_cast<int32_t>(abs_max);
// Use abs_max_int32 in subsequent calculations
float scale =
    std::max(std::abs(input_min_data[i]), std::abs(input_max_data[i]));
ranges[i] =
