rpa_read_buffer(pool_t pool, const unsigned char **data,
		const unsigned char *end, unsigned char **buffer)
{
	// Null pointer checks
	if (!pool || !data || !end || !buffer) {
		return -1; // Error code for null pointer
	}

	const unsigned char *p = *data;
	size_t len; // Using size_t to reduce overflow risk

	if (p > end) {
		return 0;
	}

	len = *p;
	p++; // Increment p after the check

	// Bounds checking before memory access
	if (p + len > end || len == 0) {
		return 0;
	}

	// Allocate memory with error checking
	*buffer = p_malloc(pool, len);
	if (!*buffer) {
		// Handle allocation failure, potentially releasing resources
		return -2; // Error code for allocation failure
	}

	memcpy(*buffer, p, len);

	*data += 1 + len;

	return len;
}
```

