                                              &params_nested_splits_in));

  // Check if params_nested_splits_in is not empty
  OP_REQUIRES(context, !params_nested_splits_in.empty(),
              errors::InvalidArgument("params_nested_splits_in cannot be empty"));

  // Check for null pointers and validate size before accessing inputs
  const Tensor* params_dense_values_in = nullptr;
  const Tensor* indices_in = nullptr;
  if (params_nested_splits_in.size() > 0) {
    params_dense_values_in = context->input(params_nested_splits_in.size());
    if (params_nested_splits_in.size() + 1 < context->num_inputs()) {
      indices_in = context->input(params_nested_splits_in.size() + 1);
    }
  }
  OP_REQUIRES(context, params_dense_values_in != nullptr,
              errors::InvalidArgument("params_dense_values_in is null"));
  OP_REQUIRES(context, indices_in != nullptr,
              errors::InvalidArgument("indices_in is null"));

  // Ensure dim_size(0) is greater than 0 to prevent underflow
  OP_REQUIRES(context, params_nested_splits_in[0].dim_size(0) > 0,
              errors::InvalidArgument("dim_size(0) must be greater than 0"));
  SPLITS_TYPE num_params = params_nested_splits_in[0].dim_size(0) - 1;

  // Enhanced validation with explicit bounds checking
  OP_REQUIRES_OK(context, ValidateIndices(indices_in, num_params, /*additional_checks=*/true));

  OP_REQUIRES(context, params_dense_values_in->dims() > 0,
              errors::InvalidArgument("params.rank must be nonzero"));
  SPLITS_TYPE num_params_dense_values = params_dense_values_in->dim_size(0);

  // Calculate the `splits`, and store the value slices that we need to
  // copy in `value_slices`.
  std::vector<std::pair<SPLITS_TYPE, SPLITS_TYPE>> value_slices;
  SPLITS_TYPE num_values = 0;
  std::vector<std::vector<SPLADEITS_TYPE>> out_splits;
  OP_REQUIRES_OK(context, MakeSplits(indices_in, params_nested_splits_in,
                                     num_params_dense_values, &out_splits,
                                     &value_slices, &num_values, /*bounds_check=*/true));

  // Write the output tensors with enhanced bounds checking
  OP_REQUIRES_OK(context, WriteSplits(out_splits, context, /*bounds_check=*/true));
  OP_REQUIRES_OK(context,
                 WriteValues(params_dense_values_in, value_slices,
                             out_splits.size(), num_values, context, /*bounds_check=*/true));
}
