    struct vmcb_control_area *c, *h, *g;
    unsigned int i;

    // Validate MAX_INTERCEPT against array sizes
    if (MAX_INTERCEPT > sizeof(((struct vmcb_control_area *)0)->intercepts) / sizeof(unsigned int)) {
        log_error("MAX_INTERCEPT exceeds array size");
        return;
    }

    vmcb_mark_dirty(svm->vmcb, VMCB_INTERCEPTS);
    if (vmcb_mark_dirty(svm->vmcb, VMCB_INTERCEPTS) != 0) { // Error Handling
        log_error("vmcb_mark_dirty failed");
        // Attempt recovery or exit
    }

    if (!is_guest_mode(&svm->vcpu))
        return;

    c = &svm->vmcb->control;
    h = &svm->vmcb01.ptr->control;
    g = &svm->nested.ctl;

    for (i = 0; i < MAX_INTERCEPT; i++)
        c->intercepts[i] = h->intercepts[i];

    if (g->int_ctl & V_INTR_MASKING_MASK) {
        /* We only want the cr8 intercept bits of L1 */
        if (vmcb_clr_intercept(c, INTERCEPT_CR8_READ) != 0) { // Error Handling
            log_error("vmcb_clr_intercept (CR8_READ) failed");
            // Attempt recovery or exit
