        if (vmcb_clr_intercept(c, INTERCEPT_VINTR) != 0) { // Error Handling
            log_error("vmcb_clr_intercept (VINTR) failed");
            // Attempt recovery or exit
        }
    }

    /* We don't want to see VMMCALLs from a nested guest */
    if (vmcb_clr_intercept(c, INTERCEPT_VMMCALL) != 0) { // Error Handling
        log_error("vmcb_clr_intercept (VMMCALL) failed");
        // Attempt recovery or exit
    }

    for (i = 0; i < MAX_INTERCEPT; i++)
        c->intercepts[i] |= g->intercepts[i];

    /* If SMI is not intercepted, ignore guest SMI intercept as well  */
    if (!intercept_smi)
        if (vmcb_clr_intercept(c, INTERCEPT_SMI) != 0) { // Error Handling
            log_error("vmcb_clr_intercept (SMI) failed");
            // Attempt recovery or exit
